/* D81 · Cửa sổ: ngăn xếp (← Quay lại / Esc lùi một cấp), thu nhỏ xuống góc (trang bên dưới vẫn dùng được), phóng to / thu về */
const DLG={stack:[],mode:null,max:false,swaps:0};  /* swaps: programmatic close() to switch modal ↔ docked; the close event is async */try{DLG.max=localStorage.getItem('cc1.dialogMax')==='1';}catch(e){}
function dlgTitle(){const h=$('#dialog-content>h2');return h?h.textContent.trim():'';}
function dlgSync(){const d=$('#dialog'),n=DLG.stack.length,b=$('#dialog-back'),mx=$('#dialog-max'),mn=$('#dialog-min');$('#dialog-title').textContent=dlgTitle()||'Cửa sổ';b.hidden=!n;b.title=n?'Quay lại: '+DLG.stack[n-1].title+' (Esc)':'';
 d.classList.toggle('max',DLG.max&&DLG.mode!=='min');d.classList.toggle('min',DLG.mode==='min');mx.setAttribute('aria-label',DLG.max?'Thu về kích thước thường':'Phóng to');mx.title=mx.getAttribute('aria-label');mx.classList.toggle('on',DLG.max);mx.hidden=DLG.mode==='min';
 mn.setAttribute('aria-label',DLG.mode==='min'?'Mở lại cửa sổ':'Thu nhỏ');mn.title=mn.getAttribute('aria-label');}
function dlgModal(){const d=$('#dialog');if(DLG.mode==='min'){DLG.swaps++;d.close();DLG.mode=null;}if(!d.open)d.showModal();}
function showDialog(html){const d=$('#dialog'),c=$('#dialog-content'),t=dlgTitle(),m=/<h2[^>]*>([\s\S]*?)<\/h2>/.exec(html),tmp=document.createElement('div');tmp.innerHTML=m?m[1]:'';const nt=tmp.textContent.trim();
 if(d.open&&c.childNodes.length&&t&&nt&&t!==nt){const f=document.createDocumentFragment();while(c.firstChild)f.appendChild(c.firstChild);DLG.stack.push({title:t,frag:f,scroll:c.scrollTop});}  // a new window: keep the previous one (its handlers stay attached)
 c.innerHTML=html;dlgModal();c.scrollTop=0;dlgSync();}
function dlgBack(){const d=$('#dialog'),c=$('#dialog-content'),x=DLG.stack.pop();if(!x){d.close();return;}c.innerHTML='';c.appendChild(x.frag);dlgModal();c.scrollTop=x.scroll;dlgSync();const f=c.querySelector('input,select,textarea,button');if(f)f.focus();}
function dlgMin(){const d=$('#dialog');if(DLG.mode==='min'){dlgModal();dlgSync();return;}DLG.swaps++;d.close();d.show();DLG.mode='min';dlgSync();$('#dialog-min').focus();}
function dlgMax(){DLG.max=!DLG.max;try{localStorage.setItem('cc1.dialogMax',DLG.max?'1':'0');}catch(e){}if(DLG.mode==='min')dlgModal(),DLG.mode=null;dlgSync();}
(()=>{const d=$('#dialog');d.addEventListener('close',()=>{if(DLG.swaps>0){DLG.swaps--;return;}DLG.stack=[];DLG.mode=null;dlgSync();});
 d.addEventListener('cancel',e=>{if(DLG.stack.length){e.preventDefault();dlgBack();}});
 $('#dialog-back').onclick=dlgBack;$('#dialog-min').onclick=dlgMin;$('#dialog-max').onclick=dlgMax;$('#dialog-title').ondblclick=dlgMax;$('#dialog-title').onclick=()=>{if(DLG.mode==='min')dlgMin();};})();
