function openImport(){const g=group();showDialog('<h2>Nạp '+esc(subs[step]?subs[step].find(x=>x[0]===g)[1]:boot.steps[step])+'</h2><label>CSV UTF-8 hoặc XLSX (tối đa 20.000 dòng, 25 MB)<input id="upload-file" type="file" accept=".csv,.xlsx"></label><div class="form-grid"><label>Trang tính<input id="import-sheet"></label><label>Dòng tiêu đề<input id="import-header" type="number" value="1" min="1" max="100"></label></div><button id="preview-file">Đọc dòng tiêu đề / xem trước</button><div id="import-preview"></div><p class="help">Ngoài BOQ: dùng đúng dòng tiêu đề CSV tải từ bảng hiện tại. Khi nạp lại, dữ liệu bảng hiện tại được thay bằng file đã chọn và phải xác nhận lại. Muốn lưu dùng chung cho nhiều hồ sơ, nạp vào "Thư viện dữ liệu".</p>');$('#preview-file').onclick=async()=>{try{const file=$('#upload-file').files[0];if(!file)throw Error('Chọn file trước.');if(file.size>25*1024*1024)throw Error('Tối đa 25 MB.');let data=await fileBase64(file);importFile={filename:file.name,data,sheet:$('#import-sheet').value,header_row:Number($('#import-header').value)};let d=await api('/api/import',importFile);$('#import-sheet').value=d.sheet;importFile.sheet=d.sheet;let html=`<p>${d.count} dòng · ${d.sheets.map(esc).join(', ')} · ${esc(d.sha256.slice(0,16))}…</p>`;if(d.warnings&&d.warnings.length)html+=`<details class="editor" open><summary>Cần kiểm khi nạp (${d.warnings.length})</summary>${d.warnings.map(w=>`<div class="question validation-question">${esc(w)}</div>`).join('')}</details>`;if(step===1)html+='<div class="form-grid">'+[['source_code','Mã nguồn'],['description','Mô tả *'],['quantity','Khối lượng *'],['uom','Đơn vị *'],['unit_price','Đơn giá nguồn'],['kind','Phân loại (cột Display Type)']].map(([k,l])=>`<label>${l}<select data-column="${k}"><option value="">Không chọn</option>${d.headers.map(h=>`<option>${esc(h)}</option>`).join('')}</select></label>`).join('')+'</div>';html+='<div class="table-wrap"><table><tbody>'+d.preview.map(r=>'<tr>'+r.slice(0,8).map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><button id="import-confirm" class="primary">Nạp vào bản nháp</button>';$('#import-preview').innerHTML=html;$('#import-confirm').onclick=async()=>{try{let request={...importFile};if(step===1)request.columns=Object.fromEntries([...document.querySelectorAll('[data-column]')].map(e=>[e.dataset.column,e.value]));else request.table=g;let actual=await api('/api/import',request);if(step===1){project.boq=actual.rows;project.mapping=[];}else project[g]=actual.records;dirty=true;selected=-1;page=0;$('#dialog').close();render();message('Đã nạp file vào nháp; kiểm tra trước khi xác nhận.');}catch(e){$('#import-preview').insertAdjacentHTML('beforeend','<p>'+esc(e.message)+'</p>');}};}catch(e){$('#import-preview').textContent=e.message;}};}
function normSearch(){showDialog('<h2>Tra cứu danh mục TT38</h2><p>Danh mục tra cứu gồm dòng tiêu đề và dòng tham chiếu. Kết quả không tự trở thành mã chi tiết đã được chọn.</p><label>Mã hoặc cụm từ tiếng Việt<input id="norm-query" placeholder="AF.651 hoặc CỐT THÉP"></label><button id="norm-find">Tìm</button><div id="norm-results" class="result-list"></div>');$('#norm-find').onclick=async()=>{try{let d=await api('/api/norm-search?q='+encodeURIComponent($('#norm-query').value));$('#norm-results').innerHTML=d.rows.map(r=>`<div class="question"><strong>${esc(r.code)}</strong> · ${esc(r.title)}<code>${esc(r.ref)} · ${esc(r.status)}</code></div>`).join('')||'<p>Không có kết quả tra cứu phù hợp. Tra bảng nguồn và ghi ngoại lệ nếu cần.</p>';}catch(e){$('#norm-results').textContent=e.message;}};}
$('#dialog-close').onclick=()=>$('#dialog').close();$('#nav-back').onclick=()=>history.back();$('#new-project').onclick=create;$('#start').onclick=create;$('#save').onclick=()=>save(false).catch(e=>message(e.message,true));$('#confirm').onclick=()=>save(true).catch(e=>message(e.message,true));$('#backup').onclick=()=>{location.href='/api/projects/'+project.id+'/backup';};
$('#open-library').onclick=libraryView;$('#open-codelib').onclick=()=>codeLibrary();$('#open-ai').onclick=()=>aiState.providers.length?aiSettings():null;
$('#restore').onclick=()=>{showDialog('<h2>Khôi phục hồ sơ trên máy</h2><p>Giữ dữ liệu đầu vào và truy vết nguồn gốc, tạo hồ sơ mới; các bước phải xác nhận lại. Nhận bản sao lưu 0.1.0 (tự chuyển sang 0.2.0) và 0.2.0. Không nhập phê duyệt doanh nghiệp từ file JSON.</p><input id="restore-file" type="file" accept=".json"><button id="restore-confirm" class="primary">Nạp hồ sơ</button>');$('#restore-confirm').onclick=async()=>{try{let f=$('#restore-file').files[0];if(!f||f.size>30*1024*1024)throw Error('Chọn JSON tối đa 30 MB.');let d=await api('/api/restore',JSON.parse(await f.text()));boot.projects=(await api('/api/bootstrap')).projects;dirty=false;$('#dialog').close();await openProject(d.project.id);}catch(e){$('#dialog-content').insertAdjacentHTML('beforeend','<p>'+esc(e.message)+'</p>');}};};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
(async()=>{try{boot=await api('/api/bootstrap');master=(await api('/api/catalog')).work_results;try{aiState=await api('/api/ai/providers');}catch(e){aiState={providers:[],active:null};}renderProjects();if(boot.projects.length)await openProject(boot.projects[0].id);}catch(e){$('#welcome').insertAdjacentHTML('beforeend','<p>'+esc(e.message)+'</p>');}})();

// D49 · CC1 × Carbon shell: light/dark theme and collapsible side nav (per-viewer preference, safe if storage is blocked)
(function(){const root=document.documentElement,store=(k,v)=>{try{v===undefined?localStorage.removeItem(k):localStorage.setItem(k,v)}catch(e){}};
const dark=()=>root.dataset.theme?root.dataset.theme==='dark':matchMedia('(prefers-color-scheme: dark)').matches;
const t=document.getElementById('theme-toggle');if(t)t.onclick=()=>{const next=dark()?'light':'dark';root.dataset.theme=next;store('cc1-theme',next);};
const n=document.getElementById('nav-collapse');if(n){const sync=()=>{const c=root.dataset.nav==='collapsed';n.setAttribute('aria-label',c?'Mở điều hướng':'Ẩn điều hướng');n.querySelector('span').textContent=c?'Mở điều hướng':'Ẩn điều hướng';};sync();
n.onclick=()=>{if(root.dataset.nav==='collapsed'){delete root.dataset.nav;store('cc1-nav');}else{root.dataset.nav='collapsed';store('cc1-nav','collapsed');}sync();};}})();
